// src/data/initialData.ts
function generateCandles(basePrice, volatility, weeks = 16) {
	const candles = [];
	let current = basePrice;
	for (let i = 1; i <= weeks; i++) {
		const change = (Math.random() - .48) * volatility * current;
		const open = Math.max(1, current);
		const close = Math.max(1, open + change);
		const high = Math.max(open, close) + Math.random() * (open * volatility * .5);
		const low = Math.max(.5, Math.min(open, close) - Math.random() * (open * volatility * .5));
		const volume = Math.floor(1e6 + Math.random() * 5e6);
		candles.push({
			week: i,
			open: Math.round(open * 100) / 100,
			high: Math.round(high * 100) / 100,
			low: Math.round(low * 100) / 100,
			close: Math.round(close * 100) / 100,
			volume
		});
		current = close;
	}
	return candles;
}
